Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    if (actualTypeArguments.length == 0) {
        return null;
    }

    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArgument = actualTypeArguments[i];
        if (typeArgument instanceof Class) {
            resolvedArguments[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
            resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
        } else {
            return null; // Cannot resolve other types like WildcardType
        }
    }

    return resolvedArguments;
}

Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0) {
        return Object.class; // Default to Object if no bounds are specified
    }

    // Check if the type variable is declared by the target type
    TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
    for (int i = 0; i < typeParameters.length; i++) {
        if (typeParameters[i].equals(typeVariable)) {
            // If the type variable is declared by the target type, we need to look at the superclass or interfaces
            Type genericSuperclass = targetType.getGenericSuperclass();
            if (genericSuperclass instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
                Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
                if (i < actualTypeArguments.length) {
                    return (Class<?>) actualTypeArguments[i];
                }
            }

            Type[] genericInterfaces = targetType.getGenericInterfaces();
            for (Type genericInterface : genericInterfaces) {
                if (genericInterface instanceof ParameterizedType) {
                    ParameterizedType parameterizedType = (ParameterizedType) genericInterface;
                    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
                    if (i < actualTypeArguments.length) {
                        return (Class<?>) actualTypeArguments[i];
                    }
                }
            }
        }
    }

    // If the type variable is not declared by the target type, we need to look at the superclass or interfaces
    Class<?> superclass = targetType.getSuperclass();
    if (superclass != null) {
        Class<?> resolved = resolveTypeVariable(typeVariable, superclass);
        if (resolved != null) {
            return resolved;
        }
    }

    for (Class<?> interfaceType : targetType.getInterfaces()) {
        Class<?> resolved = resolveTypeVariable(typeVariable, interfaceType);
        if (resolved != null) {
            return resolved;
        }
    }

    return null; // Could not resolve the type variable
}

