static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the first day of the month
    int firstDayOfMonth = 1;
    // Calculate the last day of the month
    int lastDayOfMonth = 31; // Simplified, does not account for actual month length
    if (month == 4 || month == 6 || month == 9 || month == 11) {
        lastDayOfMonth = 30;
    } else if (month == 2) {
        // Simplified, does not account for leap years
        lastDayOfMonth = 28;
    }

    // Find the closest day that is a multiple of dayStep
    int adjustedDay = ((day - 1) / dayStep) * dayStep + 1;
    if (adjustedDay < firstDayOfMonth) {
        adjustedDay = firstDayOfMonth;
    } else if (adjustedDay > lastDayOfMonth) {
        adjustedDay = lastDayOfMonth;
    }

    return year * 10000L + month * 100L + adjustedDay;
}

