LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int length = str.length();
    int utf8Length = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            utf8Length++;
        } else if (c < 0x800) {
            utf8Length += 2;
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < length && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                utf8Length += 4;
                i++; // Skip the next character as it is part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair in string");
            }
        } else {
            utf8Length += 3;
        }
    }

    LinkedBuffer buffer = lb;
    int offset = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            ensureCapacity(buffer, offset + 1);
            buffer.buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            ensureCapacity(buffer, offset + 2);
            buffer.buffer[offset++] = (byte) (0xc0 | (c >> 6));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < length && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                int codePoint = Character.toCodePoint(c, str.charAt(i + 1));
                ensureCapacity(buffer, offset + 4);
                buffer.buffer[offset++] = (byte) (0xf0 | (codePoint >> 18));
                buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                buffer.buffer[offset++] = (byte) (0x80 | (codePoint & 0x3f));
                i++; // Skip the next character as it is part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair in string");
            }
        } else {
            ensureCapacity(buffer, offset + 3);
            buffer.buffer[offset++] = (byte) (0xe0 | (c >> 12));
            buffer.buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        }
    }

    return buffer;
}

private static void ensureCapacity(LinkedBuffer buffer, int requiredCapacity) {
    if (buffer.offset + requiredCapacity > buffer.buffer.length) {
        throw new BufferOverflowException();
    }
}

