private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, extract the argument types
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String argumentTypes = descriptor.substring(1, end);
        int index = 0;
        while (index < argumentTypes.length()) {
            char type = argumentTypes.charAt(index);
            switch (type) {
                case 'B':
                case 'C':
                case 'I':
                case 'S':
                case 'Z':
                    // These types take up one slot
                    index++;
                    break;
                case 'D':
                case 'J':
                    // These types take up two slots
                    index += 2;
                    break;
                case 'L':
                    // Object type, find the end of the class name
                    index = argumentTypes.indexOf(';', index) + 1;
                    if (index == 0) {
                        throw new IllegalArgumentException("Invalid object type in descriptor");
                    }
                    break;
                case '[':
                    // Array type, skip to the end of the array descriptor
                    do {
                        index++;
                    } while (index < argumentTypes.length() && argumentTypes.charAt(index) == '[');
                    if (index < argumentTypes.length() && (argumentTypes.charAt(index) == 'L')) {
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid array type in descriptor");
                        }
                    } else if (index >= argumentTypes.length()) {
                        throw new IllegalArgumentException("Invalid array type in descriptor");
                    } else {
                        index++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + type);
            }
        }
    } else {
        // It's a field descriptor, pop based on the type
        switch (descriptor.charAt(0)) {
            case 'B':
            case 'C':
            case 'I':
            case 'S':
            case 'Z':
                // These types take up one slot
                break;
            case 'D':
            case 'J':
                // These types take up two slots
                break;
            case 'L':
                // Object type, do nothing as it's a single slot
                break;
            case '[':
                // Array type, do nothing as it's a single slot
                break;
            default:
                throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(0));
        }
    }
}

