private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, extract argument types
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String argumentTypes = descriptor.substring(1, end);
        int index = 0;
        while (index < argumentTypes.length()) {
            char type = argumentTypes.charAt(index);
            switch (type) {
                case 'B':
                case 'C':
                case 'I':
                case 'S':
                case 'Z':
                    // These types take up one slot
                    index++;
                    break;
                case 'D':
                case 'J':
                    // These types take up two slots
                    index += 2;
                    break;
                case 'F':
                case 'L':
                case '[':
                    // These types take up one slot
                    if (type == 'L') {
                        // Skip the class name
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid class descriptor in method descriptor");
                        }
                    } else if (type == '[') {
                        // Skip the array descriptor
                        while (index < argumentTypes.length() && argumentTypes.charAt(index) == '[') {
                            index++;
                        }
                        if (index == argumentTypes.length()) {
                            throw new IllegalArgumentException("Invalid array descriptor in method descriptor");
                        }
                        char arrayType = argumentTypes.charAt(index);
                        if (arrayType == 'L') {
                            index = argumentTypes.indexOf(';', index) + 1;
                            if (index == 0) {
                                throw new IllegalArgumentException("Invalid class descriptor in array descriptor");
                            }
                        } else {
                            index++;
                        }
                    } else {
                        index++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type descriptor: " + type);
            }
        }
    } else {
        // It's a type descriptor, pop the corresponding type
        switch (descriptor.charAt(0)) {
            case 'B':
            case 'C':
            case 'I':
            case 'S':
            case 'Z':
            case 'F':
                // These types take up one slot
                break;
            case 'D':
            case 'J':
                // These types take up two slots
                break;
            case 'L':
            case '[':
                // These types take up one slot
                break;
            default:
                throw new IllegalArgumentException("Invalid type descriptor: " + descriptor.charAt(0));
        }
    }
}

